"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["10783"],{93749(e,t,i){i.r(t),i.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>u,assets:()=>l});var a=JSON.parse('{"id":"equalitystory","title":"","description":"2006/3/17 2113","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/equalitystory.md","sourceDirName":".","slug":"/equalitystory","permalink":"/en/equalitystory","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"equalitystory","title":"","hide_table_of_contents":true,"sidebar_label":"Stripped the Underwear Off the \\"Equality Myth\\"! (2006/3/17 21:50:13)"},"sidebar":"timelineSidebar","previous":{"title":"Chiang Kai-shek Naturally Had the Right and Necessity to Take Coercive Measures Against Yang Hucheng and Zhang Xueliang (2006/3/17 20:06:26)","permalink":"/en/timeline/confucius/20060317"},"next":{"title":"People Cannot Be Without Sex, But Can Be Without Humanity! (2006/3/18 14:24:12)","permalink":"/en/nohumanity"}}'),o=i(74848),n=i(28453);let s={id:"equalitystory",title:"",hide_table_of_contents:!0,sidebar_label:'Stripped the Underwear Off the "Equality Myth"! (2006/3/17 21:50:13)'},r='Stripping the Underwear Off the "Myth of Equality"!',l={},u=[];function h(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"stripping-the-underwear-off-the-myth-of-equality",children:'Stripping the Underwear Off the "Myth of Equality"!'})}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:"2006/3/17 21:50:13"}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"The existence of classes means equality is mythical, non-real. Since class struggle is the sun of human history and does not cease to exist because some people are displeased by it, all promises of equality in reality are nothing but shameless lies dressed up in class struggle."}),"\n",(0,o.jsx)(t.p,{children:"There are innumerable promises of equality in reality: equality of outcomes, equality of process, equality of starting points, equality before the law, ultimate religious equality -- this equality, that equality. In truth, it's precisely because equality doesn't exist that all these varieties of equality nonsense get spouted. For these garbage myths of equality, there's no skin left to flay -- they've long been shameless. Since they have no skin, let's just strip the underwear off the \"myth of equality\" and expose them naked for the spectacle!"}),"\n",(0,o.jsx)(t.p,{children:"So-called equality of outcomes, process, starting points, law, ultimate religion, and so on -- none can obscure the true picture of real class struggle. Without reality, where would all this nonsense about outcomes, process, starting points, law, and ultimate religion come from? The reality of outcomes, process, starting points, law, and ultimate religion all derives from the true picture of real class struggle. Promises of equality in outcomes, process, starting points, law, and ultimate religion are all designed solely to mask the real inequality in outcomes, process, starting points, law, and ultimate religion."}),"\n",(0,o.jsx)(t.p,{children:'A very simple example: take the "equality of starting points" that many people love to mouth off about. I ask you, is there an abstract starting point that exists apart from reality? Obviously not! What constitutes the real starting point is reality itself. How can the inequality of reality possibly produce equality of starting points? All inequalities are real and therefore historical. The forms of inequality change historically. To babble about equality without confronting this historically changing reality of inequality -- you\'ve either got too much water in your brain or too many ghosts in your heart!'}),"\n",(0,o.jsx)(t.p,{children:"The real backdrop of inequality is nothing but the most real manifestation of class struggle. Historical reality is the ongoing historical reality of inequality. History is iron and blood. Even the color of roses is dyed with blood. What people strive for is always what they cannot attain. The underwear of equality flutters on the flagpole of history, and aside from provoking peculiar howls at peculiar times in peculiar places, it has no meaning whatsoever."})]})}function c(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},28453(e,t,i){i.d(t,{R:()=>s,x:()=>r});var a=i(96540);let o={},n=a.createContext(o);function s(e){let t=a.useContext(n);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:s(e.components),a.createElement(n.Provider,{value:t},e.children)}}}]);